WITH exploded AS (SELECT id, host, log_ts, level, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, attr_value) SELECT host, DATE_TRUNC('DAY', log_ts) AS activity_day, level, MAX(log_ts) AS ended_at, ROUND(AVG(status_code), 2) AS avg_status_code, COUNT(CASE WHEN level = 'WARN' THEN 1 END) AS warn_count, GROUPING_ID() AS grouping_id FROM exploded GROUP BY CUBE (host, DATE_TRUNC('DAY', log_ts), level) HAVING ROUND(AVG(status_code), 2) > 0 ORDER BY host DESC;
